<div class="card p-3"><table class="table table-hover dt"><thead><tr><th>Kode</th><th>Booking</th><th>Jenis</th><th>Metode</th><th>Nominal</th><th>Status</th><th>Bukti</th><th>Tindakan</th></tr></thead><tbody>
<?php foreach ($rows as $r): ?><tr><td><?= e($r->payment_code) ?></td><td><?= e($r->booking_code) ?></td><td><?= e($r->kind) ?></td><td><?= e($r->method_name) ?></td><td><?= rupiah($r->amount) ?></td><td><?= badge($r->status) ?><?= $r->reject_reason ? '<br><small class="text-danger">' . e($r->reject_reason) . '</small>' : '' ?></td>
<td><?php if ($r->proof_id): ?><a target="_blank" href="<?= site_url('partner/files/payment_proof/' . $r->proof_id) ?>">Lihat bukti</a><?php endif; ?></td>
<td><?php if ($r->status === 'waiting_verification' && in_array('payment.verify', $perms)): ?><?= post_btn('partner/payments/verify/' . $r->id, 'Verifikasi', 'btn-success', [], 'Pastikan dana sudah masuk ke rekening. Verifikasi pembayaran ini?') ?> <?= post_note('partner/payments/reject/' . $r->id, 'Tolak', 'btn-outline-danger', [], 'Alasan', 'reason', true) ?><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div>
